"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["44052"],{42195(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fase_sem_unidade_responsavel","status":422,"titulo":"Toda fase do cronograma precisa de uma unidade respons\xe1vel para o processo ser publicado"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fase_sem_unidade_responsavel","requisitos":[],"oQueAconteceu":["Ao menos uma fase do cronograma n\xe3o tem a unidade da Unifesspa que responde por ela.\\nToda fase publicada responde a uma unidade da Unifesspa, e \xe9 essa unidade que responde\\npelos atos e pelos recursos daquela fase. A mensagem de detalhe cita o c\xf3digo da\\nprimeira fase sem unidade, na ordem do cronograma. A recusa sai com **422**, antes de\\ngerar a vers\xe3o.","No rascunho a unidade \xe9 opcional, e o cronograma \xe9 gravado sem ela; quem a exige \xe9 a\\nopera\xe7\xe3o que gera vers\xe3o: a publica\xe7\xe3o e a retifica\xe7\xe3o em ato \xfanico. A consulta de conformidade do processo\\n(`GET /api/selecao/processos-seletivos/{id}/conformidade`) mostra a pend\xeancia antes da\\ntentativa."],"comoResolver":["Defina a unidade respons\xe1vel de cada fase do cronograma, no campo da fase\\n(`unidadeResponsavelId`), e reenvie o cronograma completo\\n(`PUT /api/selecao/processos-seletivos/{id}/cronograma-fases`). Repita ent\xe3o a\\npublica\xe7\xe3o ou a retifica\xe7\xe3o.","Se v\xe1rias fases est\xe3o sem unidade, a resposta cita uma de cada vez: corrija todas antes\\nde repetir."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);